public class Solution {
    static long linha(int[] v) { return faixa(v, 0, v.length - 1); }

    // dp[i] = max(dp[i-1], dp[i-2] + v[i]): a última decisão é roubar ou não a casa i.
    private static long faixa(int[] v, int de, int ate) {
        long antes2 = 0, antes1 = 0;
        for (int i = de; i <= ate; i++) {
            long atual = Math.max(antes1, antes2 + v[i]);
            antes2 = antes1;
            antes1 = atual;
        }
        return antes1;
    }

    // Circular: ou a primeira fica de fora, ou a última.
    static long circular(int[] v) {
        if (v.length == 1) return v[0];
        return Math.max(faixa(v, 0, v.length - 2), faixa(v, 1, v.length - 1));
    }
}

