import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static long bruta(int[] v, boolean circ) {
        long melhor = 0;
        int n = v.length;
        for (int m = 0; m < 1 << n; m++) {
            if ((m & (m << 1)) != 0) continue;
            if (circ && n > 1 && (m & 1) == 1 && (m >> (n - 1) & 1) == 1) continue;
            long s = 0;
            for (int i = 0; i < n; i++) if ((m >> i & 1) == 1) s += v[i];
            melhor = Math.max(melhor, s);
        }
        return melhor;
    }

    @Test void exemplos() {
        assertEquals(12, Solution.linha(new int[]{2, 7, 9, 3, 1}));
        assertEquals(3, Solution.circular(new int[]{2, 3, 2}));
        assertEquals(0, Solution.linha(new int[]{}));
        assertEquals(5, Solution.circular(new int[]{5}));
    }

    @Test void aleatorioContraBruta() {
        var rnd = new Random(7);
        for (int t = 0; t < 300; t++) {
            int[] v = rnd.ints(1 + rnd.nextInt(12), 0, 50).toArray();
            assertEquals(bruta(v, false), Solution.linha(v));
            assertEquals(bruta(v, true), Solution.circular(v));
        }
    }

    @Test void grandeEmLong() {
        int[] v = new int[100_000];
        Arrays.fill(v, 1_000_000_000);
        assertEquals(50_000L * 1_000_000_000, Solution.linha(v));
    }
}

