public class Solution {
    private static final int MOD = 1_000_000_007;

    // dp[i] = formas do prefixo de tamanho i; a última letra usa 1 ou 2 dígitos.
    static int formas(String s) {
        long antes2 = 1, antes1 = s.isEmpty() || s.charAt(0) == '0' ? 0 : 1;
        if (s.isEmpty()) return 1;
        for (int i = 2; i <= s.length(); i++) {
            long atual = 0;
            if (s.charAt(i - 1) != '0') atual += antes1;
            int dois = (s.charAt(i - 2) - '0') * 10 + (s.charAt(i - 1) - '0');
            if (dois >= 10 && dois <= 26) atual += antes2;
            antes2 = antes1;
            antes1 = atual % MOD;
        }
        return (int) antes1;
    }
}

