import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void exemplos() {
        assertEquals(2, Solution.formas("12"));
        assertEquals(3, Solution.formas("226"));
        assertEquals(0, Solution.formas("06"));
        assertEquals(1, Solution.formas("10"));
        assertEquals(0, Solution.formas("100"));
        assertEquals(1, Solution.formas("27"));
    }

    @Test void fibonacci() {
        assertEquals(89, Solution.formas("1".repeat(10)));
    }

    @Test void grandeModulo() {
        // "1" repetido n vezes dá Fib(n + 1); para n = 100 000 o valor só cabe módulo 10^9 + 7.
        long a = 1, b = 1;
        for (int i = 2; i <= 100_000; i++) { long c = (a + b) % 1_000_000_007; a = b; b = c; }
        assertEquals((int) b, Solution.formas("1".repeat(100_000)));
    }
}
